'use strict';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value)) result[key] = clone(value[key]);
    return result;
  }
  return value;
}

function prepareRevisionUpdate(update) {
  if (!isPlainObject(update)) throw new TypeError('update must be a plain object');

  for (const key of ['assign', 'defaults', 'increment']) {
    if (key in update && !isPlainObject(update[key])) {
      throw new TypeError(`${key} must be a plain object`);
    }
  }

  const result = clone(update);
  delete result.revision;

  for (const key of ['assign', 'defaults']) {
    if (key in result) {
      delete result[key].revision;
      if (key === 'assign' && Object.keys(result[key]).length === 0) delete result[key];
    }
  }

  if (!('increment' in result)) result.increment = {};
  result.increment.revision = 1;
  return result;
}

module.exports = { prepareRevisionUpdate };

