'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['prepareRevisionUpdate']);
const { prepareRevisionUpdate } = api;

const input = {
  revision: 99,
  title: 'release',
  metadata: { labels: ['stable'], nested: { enabled: true } },
  assign: { revision: 4, owner: { name: 'Forge' } },
  defaults: { revision: 2 },
  increment: { revision: 8, attempts: 3, history: [1, 2] }
};
const original = structuredClone(input);
const result = prepareRevisionUpdate(input);
assert.deepStrictEqual(input, original);
assert.deepStrictEqual(result, {
  title: 'release',
  metadata: { labels: ['stable'], nested: { enabled: true } },
  assign: { owner: { name: 'Forge' } },
  increment: { revision: 1, attempts: 3, history: [1, 2] }
});
assert.notStrictEqual(result, input);
assert.notStrictEqual(result.metadata, input.metadata);
assert.notStrictEqual(result.metadata.labels, input.metadata.labels);
assert.notStrictEqual(result.assign, input.assign);
assert.notStrictEqual(result.assign.owner, input.assign.owner);
assert.notStrictEqual(result.increment, input.increment);
assert.notStrictEqual(result.increment.history, input.increment.history);

result.metadata.labels.push('changed');
result.assign.owner.name = 'Other';
result.increment.history.push(3);
assert.deepStrictEqual(input, original);
input.metadata.nested.enabled = false;
assert.equal(result.metadata.nested.enabled, true);

assert.deepStrictEqual(prepareRevisionUpdate({ revision: 1 }), {
  increment: { revision: 1 }
});
assert.deepStrictEqual(prepareRevisionUpdate({
  assign: {},
  defaults: { revision: 7 },
  increment: { extra: 'kept' }
}), { increment: { extra: 'kept', revision: 1 } });

for (const invalid of [null, [], new Date(0), 'update', 4]) {
  assert.throws(() => prepareRevisionUpdate(invalid), TypeError);
}
for (const [key, value] of [
  ['assign', []], ['assign', null], ['defaults', 'bad'],
  ['defaults', []], ['increment', 1], ['increment', []]
]) {
  assert.throws(() => prepareRevisionUpdate({ [key]: value }), TypeError);
}

